<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import {useProjectStore} from '../stores/project';
import {createCommandRunner} from '../lib/commands';
import {recoverSettingsCommand} from '../lib/settings';
import type {StudioSettingsScope,StudioMemberPage,StudioMemberMetadata,StudioMemberCommandRequest} from '@loreviva/sdk-ts';
import FieldErrors from './FieldErrors.vue';
const p=defineProps<{scope:StudioSettingsScope}>();const s=useProjectStore();const page=ref<StudioMemberPage>();const selected=ref<StudioMemberMetadata>();const pairIndex=ref(0);const effect=ref<'ALLOW'|'DENY'>('ALLOW');const enabled=ref(true);const expires=ref('');const credentialEnabled=ref(true);const credentialExpiry=ref('');const error=ref<unknown>();const message=ref('');const runner=createCommandRunner(s.client);
const pair=computed(()=>page.value?.delegable_pairs[pairIndex.value]);
async function load(cursor?:string){try{page.value=await s.client.call('listAdminMembers',{query:{...p.scope,limit:50,...(cursor?{cursor}:{})}});selected.value=undefined;pairIndex.value=0;error.value=undefined}catch(e){error.value=e}}
function choose(member:StudioMemberMetadata){selected.value=JSON.parse(JSON.stringify(member));credentialEnabled.value=member.enabled;credentialExpiry.value=member.expires_at??'';effect.value='ALLOW';enabled.value=true;expires.value=''}
// Build member commands from the selected revision and returned delegable pair; credential-state edits require the tenant scope here. These UI checks do not replace the server's current-authority checks. Recovery reads the original command receipt.
async function grant(){try{if(!selected.value||!pair.value)throw Error('请选择登记成员与当前可委派动作');const body:StudioMemberCommandRequest={kind:'SET_SCOPE_GRANT',scope:p.scope,credential_id:selected.value.credential_id,subject_id:selected.value.subject_id,expected_revision:selected.value.grant_set_revision,grant:{scope:pair.value.scope,action:pair.value.action,use:pair.value.use,effect:effect.value,enabled:enabled.value,expires_at:expires.value?new Date(expires.value).toISOString():null} as Extract<StudioMemberCommandRequest,{kind:'SET_SCOPE_GRANT'}>['grant']};const receipt=await runner.run('commandAdminMembers',{headers:{'Idempotency-Key':crypto.randomUUID()},body});message.value='成员动作已提交，修订 '+receipt.result_revision;await load()}catch(e){error.value=e}}
async function credential(){try{if(!selected.value||p.scope.scope_type!=='TENANT')throw Error('凭据状态只能在租户范围由当前维护者修改');const receipt=await runner.run('commandAdminMembers',{headers:{'Idempotency-Key':crypto.randomUUID()},body:{kind:'SET_CREDENTIAL_STATE',scope:p.scope,credential_id:selected.value.credential_id,subject_id:selected.value.subject_id,expected_revision:selected.value.credential_revision,enabled:credentialEnabled.value,expires_at:credentialExpiry.value?new Date(credentialExpiry.value).toISOString():null}});message.value='凭据状态已提交，修订 '+receipt.result_revision;await load()}catch(e){error.value=e}}
async function recover(){try{await recoverSettingsCommand(s.client);message.value='已取回原成员回执';await load()}catch(e){error.value=e}}
onMounted(()=>load());
</script>
<template><section class="panel"><h2>已登记成员与动作</h2><p>只展示当前范围。授权不能替代来源、世界参与资格或私人资料许可。创建凭据由本机明确登记入口完成，此页不会生成或展示密钥。修改自己的动作仍须在提交时保有当前委派资格；若因此被拒绝，原权限不变，可由另一位当前有权成员执行撤回。</p><FieldErrors :error="error"/><p v-if="message" role="status">{{message}}</p><button @click="load()">重新读取第一页</button><template v-if="page"><table><thead><tr><th>成员</th><th>当前凭据</th><th>动作</th></tr></thead><tbody><tr v-for="member in page.items" :key="member.credential_id"><td>{{member.subject_id}} · {{member.credential_id}}</td><td>{{member.enabled?'启用':'禁用'}} · {{member.expires_at??'无期限'}}</td><td><button @click="choose(member)">查看与编辑</button></td></tr></tbody></table><button v-if="page.next_cursor" @click="load(page.next_cursor)">下一页</button><section v-if="selected"><h3>{{selected.subject_id}} 的当前动作</h3><ul><li v-for="grant in selected.grants" :key="grant.action+'/'+grant.use">{{grant.action}} / {{grant.use}} · {{grant.effect}} · {{grant.enabled?'启用':'停用'}} · {{grant.expires_at??'无期限'}} · 修订 {{grant.revision}}</li></ul><label>当前可委派的动作与用途<select v-model="pairIndex"><option v-for="(grant,i) in page.delegable_pairs" :key="grant.action+'/'+grant.use" :value="i">{{grant.action}} / {{grant.use}}</option></select></label><p v-if="pair" class="muted">期限上限：{{pair.max_expires_at??'当前登记未设置期限上限'}}。权限范围 {{pair.scope.scope_type}}。</p><label>决定<select v-model="effect"><option value="ALLOW">允许</option><option value="DENY">拒绝</option></select></label><label><input v-model="enabled" type="checkbox">启用该登记动作</label><label>到期时间（ISO 8601；留空表示无期限）<input v-model="expires" placeholder="2026-11-01T00:00:00Z"></label><button :disabled="!pair" @click="grant">保存这个动作</button><button @click="selected=undefined">取消成员修改</button><fieldset v-if="scope.scope_type==='TENANT'"><legend>整个凭据的状态</legend><p>影响该凭据所有操作。不能移除最后一位当前有效、无期限的维护者；服务器会在同一事务检查真实替代者。</p><label><input v-model="credentialEnabled" type="checkbox">凭据启用</label><label>凭据到期（ISO 8601；留空表示无期限）<input v-model="credentialExpiry"></label><button @click="credential">保存凭据状态</button></fieldset></section></template><button v-if="runner.pending.value?.operation==='commandAdminMembers'" @click="recover">查原成员命令回执</button></section></template>
